"""Static interchange version of the conversation screens in Figma."""

CHAT_CSS = '''
.chat-screen{background:#fff}.chat-nav{height:80px;padding:0 48px;display:flex;align-items:center;justify-content:space-between}.chat-nav .logo{font-size:30px;gap:6px}.chat-nav .logo svg{width:26px;height:26px}.new-chat{display:flex;gap:9px;align-items:center;border:0;background:transparent;color:#55675c;font-size:14px;padding:10px}.new-chat .icon{width:18px;height:18px}.chat-welcome{position:absolute;width:760px;left:340px;top:338px;text-align:center}.chat-welcome h1{font-size:34px;line-height:46px;font-weight:600;letter-spacing:0}.chat-welcome p{font-size:17px;line-height:28px;color:#637568;margin-top:14px}.chat-composer{position:absolute;left:340px;width:760px;border:1px solid #d7dfd8;border-radius:16px;padding:18px 20px;background:#fff}.chat-entry{font-size:17px;line-height:28px;color:#182c25}.chat-entry.placeholder{color:#69786d}.composer-actions{display:flex;align-items:center;justify-content:space-between;margin-top:16px;height:36px;color:#69786d;font-size:12px}.chat-send{width:36px;height:36px;border:0;border-radius:50%;background:#164e39;color:#fff;display:flex;align-items:center;justify-content:center}.chat-send .icon{width:20px;height:20px;transform:rotate(-90deg)}.chat-send.disabled{background:#dce4dd}.chat-suggestions{position:absolute;left:340px;top:610px;width:760px;display:flex;justify-content:center;gap:10px}.chat-suggestions>button{width:180px;height:40px;border:1px solid #e1e7e2;background:transparent;border-radius:10px;font-size:14px;color:#55675c}.chat-foot{position:absolute;left:340px;top:964px;width:760px;font-size:12px;line-height:20px;color:#69786d;text-align:center}.chat-thread{position:absolute;left:340px;width:760px;top:144px;display:flex;flex-direction:column;gap:30px}.chat-thread.ready{top:112px;gap:24px}.user-message{display:flex;justify-content:flex-end}.user-bubble{background:#f1f4f0;border-radius:16px;padding:14px 20px;font-size:17px;line-height:28px;width:540px}.user-bubble.first{width:480px}.user-bubble.budget{width:286px}.assistant-message{display:flex;gap:18px;align-items:flex-start}.assistant-message>.logo{width:26px;flex-shrink:0}.assistant-message>.logo svg{width:26px;height:26px}.assistant-copy{width:716px;display:flex;flex-direction:column;gap:12px;font-size:17px;line-height:28px}.chat-criteria>div{height:46px;border-bottom:1px solid #e6ebe5;display:flex;align-items:center;gap:14px;font-size:16px;line-height:26px}.chat-criteria span:first-child{width:20px;color:#69786d;font-size:13px}.chat-criteria span:nth-child(2){width:420px}.chat-criteria b{margin-left:auto;color:#164e39;font-weight:600}.chat-target-note{font-size:13px;line-height:22px;color:#637568}.chat-count{font-size:12px;line-height:20px;color:#69786d}.chat-confirm{width:268px;height:48px;background:#164e39;color:white;border:0;border-radius:10px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;font-size:15px;font-weight:600}.chat-confirm .icon{width:18px;height:18px}
'''

CHAT_CSS += """
.inline-stores{display:flex;flex-direction:column;gap:12px}.inline-store-buttons{display:flex;gap:12px}.inline-store{width:170px;height:44px;border:1px solid #cbd7ce;border-radius:10px;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 16px;color:#164e39;text-decoration:none;font-size:15px;font-weight:600;line-height:24px}.inline-store .icon{width:16px;height:16px}.inline-connected{display:flex;align-items:center;gap:7px;color:#637568;font-size:12px;line-height:20px}.inline-connected .icon{width:15px;height:15px}.install-chat .assistant-copy{gap:16px}.install-chat h2{font-size:20px;font-weight:600;line-height:30px;letter-spacing:0}.install-chat .user-bubble{width:226px}.install-status{display:flex;gap:8px;align-items:center;color:#7c6d45;font-size:13px;line-height:22px}.install-status .icon{width:16px;height:16px}.inline-install-actions{display:flex;gap:12px}.install-primary{width:188px;color:#fff;background:#164e39;border:0}.install-continue{width:232px}.inline-install-note{font-size:13px;line-height:22px;color:#637568}
"""

def chat_boards(screen, logo, icon):
    def nav():
        return f'<header class="chat-nav">{logo()}<button class="new-chat">{icon("edit")}New chat</button></header>'
    def composer(value, top=824, placeholder=False):
        return f'<div class="chat-composer" style="top:{top}px"><div class="chat-entry {"placeholder" if placeholder else ""}">{value}</div><div class="composer-actions"><span>Press Enter to send</span><button class="chat-send {"disabled" if placeholder else ""}" aria-label="Send message">{icon("arrow")}</button></div></div>'
    def foot():
        return '<p class="chat-foot">Chat with fits to define up to four shopping criteria.</p>'
    def user(value, cls=''):
        return f'<div class="user-message"><div class="user-bubble {cls}">{value}</div></div>'
    def assistant(value):
        return f'<div class="assistant-message">{logo(True)}<div class="assistant-copy">{value}</div></div>'
    initial = 'I need wireless headphones for my commute.'
    purpose = "Mostly on the subway. I'd like something light,<br>with a battery that lasts."
    budget = '$150, including shipping.'
    start = nav()+'<div class="chat-welcome"><h1>What are you shopping for?</h1><p>Tell us what you have in mind. We\'ll work out what to look for.</p></div>'+composer(initial,464)+'<div class="chat-suggestions"><button>Carry-on luggage</button><button>Everyday running shoes</button><button>Home office monitor</button></div>'+foot()
    discussion = nav()+'<div class="chat-thread">'+user(initial,'first')+assistant('Great. Where will you use them most?')+user(purpose)+assistant("I'll focus on noise cancellation, weight and battery life.<br>What's your budget, including shipping?")+'</div>'+composer(budget)+foot()
    rows=[('1','Noise cancellation','Required'),('2','Lightweight','250 g or less'),('3','Battery life','30+ hours'),('4','Total including shipping','$150 or less')]
    result='<p>Got it. I\'ll check these four things for you.</p><div class="chat-criteria">'+''.join(f'<div><span>{n}</span><span>{label}</span><b>{value}</b></div>' for n,label,value in rows)+'</div><p class="chat-target-note">250 g and 30 hours are suggested targets. Tell me if you\'d like to change them.</p><div class="inline-stores"><p>Where would you like to shop?</p><div class="inline-store-buttons">'+''.join(f'<a class="inline-store" href="{url}" target="{target}" rel="noopener">{name}{icon("external")}</a>' for name,url,target in [('Amazon','#screen-05','_self'),('AliExpress','https://www.aliexpress.com/w/wholesale-wireless-noise-cancelling-headphones.html','_blank'),('eBay','https://www.ebay.com/sch/i.html?_nkw=wireless+noise+cancelling+headphones','_blank'),('Rakuten','https://search.rakuten.co.jp/search/mall/wireless+noise+cancelling+headphones/','_blank')])+'</div><p class="inline-connected">'+icon('check')+'fits is connected. Your 4 criteria will follow you.</p></div>'
    ready=nav()+'<div class="chat-thread ready">'+user(purpose)+assistant("What's your budget, including shipping?")+user(budget,'budget')+assistant(result)+'</div>'+composer('e.g. Make the weight limit 200 g.',placeholder=True)+foot()
    setup=nav()+'<div class="chat-thread install-chat">'+user("Let's search on Amazon.")+assistant('<h2>One quick step before Amazon.</h2><p>Add fits to Chrome to check products as you browse.<br>Your four criteria will be ready when you get there.</p><p class="install-status">'+icon('info')+'Extension not connected</p><div class="inline-install-actions"><button class="inline-store install-primary">Add to Chrome'+icon('external')+'</button><a class="inline-store install-continue" href="#screen-05">Check &amp; open Amazon'+icon('external')+'</a></div><p class="inline-install-note">Install in Chrome, then return here and check the connection.</p><p class="inline-install-note">Your 4 criteria are saved. No need to start over.</p>')+'</div>'+composer('Ask about your criteria...',placeholder=True)+foot()
    return [screen('01','Start a conversation',start,'chat-screen'),screen('02','Talk through your needs',discussion,'chat-screen'),screen('02b','Pick a store in chat',ready,'chat-screen'),screen('03b','Extension setup in chat',setup,'chat-screen')]
